import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------------------------------------------------------------------------
# CUDA kernel (naïve but functionally correct)
# ---------------------------------------------------------------------------
cuda_source = r'''
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math_constants.h>

template <typename scalar_t>
__device__ __forceinline__ float dot_half(const scalar_t* a, const scalar_t* b, int D) {
    float acc = 0.0f;
    for (int d = 0; d < D; ++d) {
        acc += __half2float(a[d]) * __half2float(b[d]);
    }
    return acc;
}

extern "C"
__global__ void attn_forward_kernel(
    const half* __restrict__ Q,
    const half* __restrict__ K,
    const half* __restrict__ V,
    half* __restrict__ out,
    const int B,
    const int H,
    const int S,
    const int D)
{
    // blockIdx.x : batch * heads
    // blockIdx.y : sequence position i (row of Q)
    // threadIdx.x : embedding dimension d (output feature)
    const int bh = blockIdx.x;          // 0 .. B*H-1
    const int i  = blockIdx.y;          // 0 .. S-1
    const int d  = threadIdx.x;         // 0 .. D-1

    if (d >= D) return;

    // Pointers to the start of this (b, h) slice
    const half* Q_ptr = Q + ((bh * S) + i) * D;          // Q[i, :]
    const half* K_ptr = K + (bh * S) * D;                // K[0:S, :]
    const half* V_ptr = V + (bh * S) * D;                // V[0:S, :]

    // -----------------------------------------------------------------------
    // 1) Compute max score for numerical stability
    // -----------------------------------------------------------------------
    float max_score = -CUDART_INF_F;
    const float scale = rsqrtf(static_cast<float>(D));

    for (int j = 0; j < S; ++j) {
        const half* K_row = K_ptr + j * D;
        float score = dot_half<half>(Q_ptr, K_row, D) * scale;
        if (score > max_score) max_score = score;
    }

    // -----------------------------------------------------------------------
    // 2) Compute sum of exp(score - max)
    // -----------------------------------------------------------------------
    float sum_exp = 0.0f;
    for (int j = 0; j < S; ++j) {
        const half* K_row = K_ptr + j * D;
        float score = dot_half<half>(Q_ptr, K_row, D) * scale;
        sum_exp += expf(score - max_score);
    }

    // -----------------------------------------------------------------------
    // 3) Weighted sum over V using the softmax weights
    // -----------------------------------------------------------------------
    float out_val = 0.0f;
    for (int j = 0; j < S; ++j) {
        const half* K_row = K_ptr + j * D;
        const half* V_row = V_ptr + j * D + d;  // element d of V[j]
        float score = dot_half<half>(Q_ptr, K_row, D) * scale;
        float weight = expf(score - max_score) / sum_exp;
        out_val += weight * __half2float(*V_row);
    }

    // Write result
    out[((bh * S) + i) * D + d] = __float2half(out_val);
}
'''

# Compile the inline extension
attn_ext = load_inline(
    name='attn_ext',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['attn_forward_kernel'],
    verbose=False,
)

# ---------------------------------------------------------------------------
# Autograd Function wrapper
# ---------------------------------------------------------------------------
class ScaledDotProductAttentionFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, Q, K, V):
        assert Q.is_cuda and K.is_cuda and V.is_cuda
        assert Q.dtype == torch.float16 and K.dtype == torch.float16 and V.dtype == torch.float16

        B, H, S, D = Q.shape
        # Allocate output tensor
        out = torch.empty_like(Q)

        # Launch kernel
        threads = D if D <= 1024 else 1024          # CUDA max 1024 threads per block
        blocks = (B * H, S)

        stream = torch.cuda.current_stream().cuda_stream

        attn_ext.attn_forward_kernel(
            Q,
            K,
            V,
            out,
            B,
            H,
            S,
            D,
            grid=blocks,
            block=(threads, 1, 1),
            stream=stream,
        )

        return out

    @staticmethod
    def backward(ctx, grad_output):
        raise NotImplementedError("Backward pass not implemented for the custom kernel.")


# ---------------------------------------------------------------------------
# Model using the custom kernel
# ---------------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Ensure tensors are contiguous and half precision
        Q = Q.contiguous().half()
        K = K.contiguous().half()
        V = V.contiguous().half()
        return ScaledDotProductAttentionFunction.apply(Q, K, V)


