    batch_size = 32
    num_heads = 32
    sequence_length = 512
    embedding_dimension = 1024
    Q = torch.rand(batch_size, num_heads, sequence_length, embedding_dimension,
                   device='cuda', dtype=torch.float16)
    K = torch.rand(batch_size, num_heads, sequence_length, embedding_dimension,
                   device='cuda', dtype=torch.float16)
    V = torch.rand(batch_size, num_heads, sequence_length, embedding_dimension,
                   device='cuda', dtype=torch.float16)
    return [Q, K, V]

def get_init_inputs():
    return []

# Example sanity check (can be removed in production)
if __name__ == "__main__":
    model_ref = nn.Module()
    model_ref.forward = lambda Q, K, V: torch.nn.functional.scaled_dot_product_attention(Q, K, V)

    model_new = ModelNew()

    Q, K, V = get_inputs()
    out_ref = model_ref.forward(Q, K, V)
    out_new = model_new(Q, K, V)

    max_diff = (out_ref - out_new).abs().max()
